const embedded=window.parent!==window;
if(embedded){document.documentElement.classList.add('vendor-voice');const style=document.createElement('style');style.textContent='aside,main>header{display:none!important}main{margin-left:0!important}#app{padding:22px!important}.voice-layout{grid-template-columns:1fr 1fr!important}';document.head.append(style);}
window.addEventListener('message',async event=>{if(event.origin!==location.origin||event.source!==parent)return;if(event.data?.type==='bubs-vendor-context'){state.type=event.data.category;state.data={...event.data.data};voice.draft={...event.data.data};state.page='voice';render();const h=document.querySelector('.heading h1');if(h)h.textContent='Tell your story. Build your listing.';}if(event.data?.type==='bubs-end-voice'){await stopVoice('Session ended');sendVendorDraft();}});
function sendVendorDraft(){const data={};const evidence={};for(const p of voice.proposals.filter(p=>p.applied)){const key=p.field==='delivery'?'extra':p.field;data[key]=voice.draft[p.field];evidence[key]=state.data.voiceEvidence?.[p.field];}parent.postMessage({type:'bubs-vendor-updates',data,evidence},location.origin)}
if(embedded){const banner=document.createElement('div');banner.style='padding:12px 25px;background:#eadce2;display:flex;justify-content:space-between;align-items:center';banner.innerHTML='<span>Describe your own business. Apply the suggestions you want to keep.</span><button class="primary" id="return-vendor">Use applied details & return →</button>';document.body.prepend(banner);document.getElementById('return-vendor').onclick=async()=>{await stopVoice('Session ended');sendVendorDraft();parent.document.getElementById('assistant').close();};}
